// HTML 转义工具（用于纯文本段落里的 < > &，但要保留已有的 <span> 内联标签）
// 因为 md 里已含 <span style="color:..."> 内联样式，我们要保留；所以不能整体转义。
// 策略：只对段落文本做最小处理 —— 不转义，因为 md 来源可信（已保存的原文）。

// 将 md 图片引用 `![alt](images/xxx.png|jpg)` 替换为 `<img src={imageMap[xxx]} alt="alt" />`
const replaceImage = (line) => {
  return line.replace(/!\[([^\]]*)\]\(images\/([\w-]+)\.(?:png|jpg)\)/g, (match, alt, key) => {
    const src = imageMap[key];
    if (!src) return match;
    return `<img src="${src}" alt="${alt}" />`;
  });
};

// 加粗 **xxx** -> <strong>xxx</strong>（但不处理已有 <strong> 标签内的）
const replaceBold = (text) => {
  return text.replace(/\*\*([^\*]+)\*\*/g, '<strong>$1</strong>');
};

// 删除线 ~~xxx~~ -> <del>xxx</del>
const replaceDel = (text) => {
  return text.replace(/~~([^~]+)~~/g, '<del>$1</del>');
};

// 章节锚点 id 生成
let headingSeq = 0;
const makeHeadingId = (text) => {
  headingSeq += 1;
  // 去标签 + 去特殊字符
  const clean = text.replace(/<[^>]+>/g, '').replace(/[^\w一-龥]+/g, '-').replace(/^-+|-+$/g, '');
  return `chronicles-h-${headingSeq}-${clean}`;
};

// 解析 md 为 HTML 字符串
// 支持：## / ### 标题、> 引用（含 <span> 内联色）、![]() 图片、**加粗**、~~删除线~~、段落 <p>、--- 分隔
// 来源 md 正文可信（已保存原文），内联 <span style="color:..."> 保留。
const parseMarkdown = (md) => {
  const lines = md.split(/\r?\n/);
  const out = [];
  let i = 0;
  let inBlockquote = false;
  let blockquoteBuf = [];
  let paragraphBuf = [];
  const headings = []; // 目录锚点

  const flushParagraph = () => {
    if (paragraphBuf.length) {
      const content = paragraphBuf.join(' ');
      if (content.trim()) {
        out.push(`<p>${content}</p>`);
      }
      paragraphBuf = [];
    }
  };

  const flushBlockquote = () => {
    if (blockquoteBuf.length) {
      // 把每行用 <br> 拼接，保留 <span> 内联色
      const inner = blockquoteBuf.join('<br />');
      out.push(`<blockquote>${inner}</blockquote>`);
      blockquoteBuf = [];
    }
    inBlockquote = false;
  };

  while (i < lines.length) {
    let line = lines[i];
    // 去行尾 \r
    line = line.replace(/\r$/, '');

    // 图片行：单独成段，alt 作为图注
    if (/^\s*!\[([^\]]*)\]\(images\/[\w-]+\.(?:png|jpg)\)\s*$/.test(line)) {
      flushParagraph();
      flushBlockquote();
      const replaced = replaceImage(line.trim());
      out.push(`<p class="chronicles-img-p">${replaced}</p>`);
      i++;
      continue;
    }

    // 分隔线 ---
    if (/^\s*---+\s*$/.test(line)) {
      flushParagraph();
      flushBlockquote();
      out.push('<hr />');
      i++;
      continue;
    }

    // 标题 ## / ###
    const h2 = line.match(/^##\s+(.+)$/);
    const h3 = line.match(/^###\s+(.+)$/);
    const h1 = line.match(/^#\s+(.+)$/);
    if (h1) {
      flushParagraph();
      flushBlockquote();
      const inner = replaceBold(replaceDel(h1[1]));
      const id = makeHeadingId(h1[1]);
      out.push(`<h1 id="${id}">${inner}</h1>`);
      headings.push({ level: 1, text: h1[1].replace(/<[^>]+>/g, '').replace(/\*\*/g, ''), id });
      i++;
      continue;
    }
    if (h2) {
      flushParagraph();
      flushBlockquote();
      const inner = replaceBold(replaceDel(h2[1]));
      const id = makeHeadingId(h2[1]);
      out.push(`<h2 id="${id}">${inner}</h2>`);
      headings.push({ level: 2, text: h2[1].replace(/<[^>]+>/g, '').replace(/\*\*/g, ''), id });
      i++;
      continue;
    }
    if (h3) {
      flushParagraph();
      flushBlockquote();
      const inner = replaceBold(replaceDel(h3[1]));
      const id = makeHeadingId(h3[1]);
      out.push(`<h3 id="${id}">${inner}</h3>`);
      headings.push({ level: 3, text: h3[1].replace(/<[^>]+>/g, '').replace(/\*\*/g, ''), id });
      i++;
      continue;
    }

    // 引用 > 开头（支持 > <span style="color:..."> 内联）
    const quoteMatch = line.match(/^>\s?(.*)$/);
    if (quoteMatch) {
      flushParagraph();
      inBlockquote = true;
      let content = quoteMatch[1];
      content = replaceImage(content);
      content = replaceBold(content);
      content = replaceDel(content);
      blockquoteBuf.push(content);
      i++;
      continue;
    } else {
      // 如果上一个是引用，先 flush
      if (inBlockquote) {
        flushBlockquote();
      }
    }

    // 空行：段落结束
    if (line.trim() === '') {
      flushParagraph();
      i++;
      continue;
    }

    // 普通段落行：处理图片/加粗/删除线后加入段落 buffer
    let content = line;
    content = replaceImage(content);
    content = replaceBold(content);
    content = replaceDel(content);
    paragraphBuf.push(content);
    i++;
  }

  flushParagraph();
  flushBlockquote();

  return {
    html: out.join('\n'),
    headings,
  };
};

